@triton.autotune(configs=[Config({'XBLOCK': 512}, ...), Config({'XBLOCK': 1024}, ...), ...], key=['xnumel'])
@triton.jit
def kernel(in_out_ptr0, ..., xnumel, XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)[:]
    xmask = xindex < xnumel
    # ... loads and stores ...

# CORRECT: grid is a lambda that reads meta['XBLOCK']
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](arg_0, ..., xnumel)  # autotune injects XBLOCK
